import React, { useEffect, useRef } from 'react';
import * as echarts from 'echarts';

interface EChartBoxProps {
  option: echarts.EChartsCoreOption;
  className?: string;
  onChartClick?: (params: echarts.ECElementEvent) => void;
}

export const EChartBox: React.FC<EChartBoxProps> = ({
  option,
  className = 'w-full h-full',
  onChartClick,
}) => {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const chartRef = useRef<echarts.ECharts | null>(null);
  const clickHandlerRef = useRef(onChartClick);
  clickHandlerRef.current = onChartClick;

  useEffect(() => {
    const el = containerRef.current;
    if (!el) return;

    // Use canvas renderer to prevent SVG flex height feedback loops
    const instance = echarts.init(el, undefined, { renderer: 'canvas' });
    chartRef.current = instance;

    const handleClick = (params: echarts.ECElementEvent) => {
      if (clickHandlerRef.current) {
        clickHandlerRef.current(params);
      }
    };
    instance.on('click', handleClick);

    let resizeTimer: number;
    let lastWidth = 0;
    let lastHeight = 0;

    const observer = new ResizeObserver((entries) => {
      for (const entry of entries) {
        const { width, height } = entry.contentRect;
        if (Math.abs(width - lastWidth) > 1 || Math.abs(height - lastHeight) > 1) {
          lastWidth = width;
          lastHeight = height;
          cancelAnimationFrame(resizeTimer);
          resizeTimer = requestAnimationFrame(() => {
            if (chartRef.current && !chartRef.current.isDisposed()) {
              chartRef.current.resize();
            }
          });
        }
      }
    });
    observer.observe(el);

    return () => {
      cancelAnimationFrame(resizeTimer);
      observer.disconnect();
      instance.off('click', handleClick);
      instance.dispose();
      chartRef.current = null;
    };
  }, []);

  useEffect(() => {
    if (chartRef.current && !chartRef.current.isDisposed()) {
      chartRef.current.setOption(option, { notMerge: true });
    }
  }, [option]);

  return <div ref={containerRef} className={`relative overflow-hidden ${className}`} />;
};



