<template>
  <div ref="el" class="mm-chart" :style="{ height: height, width: '100%' }"></div>
</template>

<script>
import * as echarts from 'echarts'

export default {
  name: 'ChartBox',
  props: {
    option: { type: Object, required: true },
    height: { type: String, default: '100%' },
    notMerge: { type: Boolean, default: true }
  },
  data() {
    return { chart: null, ro: null }
  },
  watch: {
    option: {
      deep: true,
      handler(val) {
        if (this.chart) this.chart.setOption(val, this.notMerge)
      }
    }
  },
  mounted() {
    this.chart = echarts.init(this.$refs.el, null, { renderer: 'svg' })
    this.chart.setOption(this.option, this.notMerge)
    const resize = () => this.chart && this.chart.resize()
    window.addEventListener('resize', resize)
    if (typeof ResizeObserver !== 'undefined') {
      this.ro = new ResizeObserver(resize)
      this.ro.observe(this.$refs.el)
    }
    this._resize = resize
  },
  beforeDestroy() {
    if (this._resize) window.removeEventListener('resize', this._resize)
    if (this.ro) this.ro.disconnect()
    if (this.chart) { this.chart.dispose(); this.chart = null }
  }
}
</script>


