/**
 * 由最新版 React 源码的 data/marketData.ts 生成 Vue 版 assets/data.js（去类型、保留 ESM 导出）。
 * 用法: node scripts/gen-mm-data.mjs
 */
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'
import { createRequire } from 'node:module'

const require = createRequire(import.meta.url)
const esbuild = require('esbuild')
const repo = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const SRC = 'C:/Users/Administrator/Downloads/苏州市房地产市场数据分析平台/src/data/marketData.ts'
const OUT = path.join(repo, 'src/views/property/marketMonitor/assets/data.js')

const ts = fs.readFileSync(SRC, 'utf8')
const { code } = await esbuild.transform(ts, { loader: 'ts', format: 'esm', target: 'es2019', minify: false })
fs.writeFileSync(OUT, `/* AUTO-GENERATED from 最新版 marketData.ts by scripts/gen-mm-data.mjs — 请勿手工编辑 */\n${code}`, 'utf8')
console.log('written', OUT, code.length, 'chars')

/**
 * 由最新版 React 组件用到的 lucide-react 图标，补齐 Vue 版 assets/icons.js。
 * 保留原有图标，新增缺失项，并写入数字命名别名（building2 / maximize2 等）以兼容不同写法。
 * 用法: node scripts/gen-mm-icons.mjs
 */
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const repo = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const REACT_SRC = 'C:/Users/Administrator/Downloads/苏州市房地产市场数据分析平台/src'
const LUCIDE_DIR = 'C:/Users/Administrator/Downloads/苏州市房地产市场数据分析平台/node_modules/lucide-react/dist/esm/icons'
const ICONS_OUT = path.join(repo, 'src/views/property/marketMonitor/assets/icons.js')

const pascalToKebab = (s) => s
  .replace(/([a-z0-9])([A-Z])/g, '$1-$2')
  .replace(/([A-Za-z])([0-9])/g, '$1-$2')
  .toLowerCase()

// 收集 React 组件里 import from 'lucide-react' 的名字
const wanted = new Set()
for (const f of fs.readdirSync(path.join(REACT_SRC, 'components')).filter(x => x.endsWith('.tsx'))) {
  const t = fs.readFileSync(path.join(REACT_SRC, 'components', f), 'utf8')
  const m = t.match(/import\s*\{([^}]*)\}\s*from\s*['"]lucide-react['"]/)
  if (m) m[1].split(',').map(x => x.trim()).filter(Boolean).forEach(x => wanted.add(x))
}

// lucide 内部节点 -> icons.js 节点（去掉 key）
function readIcon(kebab) {
  const f = path.join(LUCIDE_DIR, kebab + '.js')
  if (!fs.existsSync(f)) return null
  const src = fs.readFileSync(f, 'utf8')
  const m = src.match(/const __iconNode\s*=\s*(\[[\s\S]*?\]);/)
  if (!m) return null
  // 受信任的本地包文件；数组字面量可直接求值
  const arr = new Function('return ' + m[1])()
  return arr.map(([tag, attrs]) => {
    const a = { ...attrs }
    delete a.key
    return { tag, attrs: a }
  })
}

// 读现有
const existingSrc = fs.readFileSync(ICONS_OUT, 'utf8')
const existing = JSON.parse(existingSrc.replace(/^export default\s*/, '').trim())
const icons = { ...existing }

const added = []
for (const name of wanted) {
  const kebab = pascalToKebab(name)
  const nodes = readIcon(kebab)
  if (!nodes) { console.warn('lucide 图标文件缺失:', kebab, '(from', name + ')'); continue }
  // 主名
  if (!icons[kebab]) { icons[kebab] = nodes; added.push(kebab) }
  // 数字别名（Building2 -> building2）
  const alias = kebab.replace(/-([0-9])/g, '$1')
  if (alias !== kebab && !icons[alias]) { icons[alias] = nodes; added.push(alias) }
  // 常见同义别名
  const synonyms = { home: 'house', house: 'home', 'pie-chart': 'chart-pie', 'chart-pie': 'pie-chart', 'bar-chart-3': 'chart-column', 'chart-column': 'bar-chart-3' }
  if (synonyms[kebab] && !icons[synonyms[kebab]]) { icons[synonyms[kebab]] = nodes; added.push(synonyms[kebab]) }
}

fs.writeFileSync(ICONS_OUT, '// Auto-generated: 最新版 lucide-react 图标集（scripts/gen-mm-icons.mjs）。Do not edit names.\nexport default ' + JSON.stringify(icons) + '\n', 'utf8')
console.log('icons total', Object.keys(icons).length, 'added', added.join(', ') || '(none)')

/**
 * 由最新版 React 的 Vite/Tailwind v4 构建 CSS 生成 Vue 版 assets/dashboard.css。
 * 处理：
 *  1) 拆掉 @layer 包装（避免被门户 UnoCSS/Element UI 的非分层样式压制）
 *  2) 所有选择器加 .mm-dashboard 作用域前缀，:root/:host/html/body -> .mm-dashboard
 *  3) @property / @keyframes 保持全局（自定义属性注册与动画名，不影响其它页面）
 *  4) @media / @supports 内的规则同样加作用域
 * 用法: node scripts/gen-mm-css.mjs [react-dist/assets 目录]
 */
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'
import { createRequire } from 'node:module'

const require = createRequire(import.meta.url)
const postcss = require('postcss')
const repo = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const ASSETS = process.argv[2] || 'C:/Users/Administrator/Downloads/苏州市房地产市场数据分析平台/dist/assets'
const OUT = path.join(repo, 'src/views/property/marketMonitor/assets/dashboard.css')

const cssFile = fs.readdirSync(ASSETS).find(f => f.endsWith('.css'))
if (!cssFile) throw new Error('找不到构建 CSS: ' + ASSETS)
const root = postcss.parse(fs.readFileSync(path.join(ASSETS, cssFile), 'utf8'))

// 1) 拆 @layer
root.walkAtRules('layer', (at) => {
  if (at.nodes && at.nodes.length) at.replaceWith(...at.nodes)
  else at.remove()
})

// 2) 作用域前缀
const ROOT_SEL = new Set([':root', ':host', 'html', 'body', 'html body', '*'])
function scopeOne(sel) {
  const s = sel.trim()
  if (!s) return s
  if (ROOT_SEL.has(s)) return s === '*' ? '.mm-dashboard *' : '.mm-dashboard'
  if (s.startsWith('.mm-dashboard')) return s
  if (/^::?[-a-z]/.test(s)) return '.mm-dashboard ' + s   // ::-webkit-scrollbar 等伪元素
  return '.mm-dashboard ' + s
}
root.walkRules((rule) => {
  // @keyframes 内部（0% / from / to）不加作用域
  let p = rule.parent
  while (p) {
    if (p.type === 'atrule' && /keyframes$/.test(p.name)) return
    p = p.parent
  }
  const mapped = rule.selectors.map(scopeOne)
  rule.selectors = [...new Set(mapped)]
})

// 3) 去掉 @layer 声明残留（@layer a,b,c; 已被上面 remove）
const out = '/* AUTO-GENERATED: 最新版 Tailwind v4 构建 CSS，作用域 .mm-dashboard —— scripts/gen-mm-css.mjs */\n' + root.toString()
fs.writeFileSync(OUT, out, 'utf8')
console.log('written', OUT, out.length, 'chars from', cssFile)

