function createProxyConfig(target, proxyContext) {
  const shouldStripApiPrefix = proxyContext && String(proxyContext).startsWith("/api");
  const isLocalTarget = /^https?:\/\/(localhost|127\.0\.0\.1|\[::1\]|192\.168\.)/i.test(target || "");
