    envDir: rootDir + "/env",
    build: {
      outDir: rootDir + "/dist",
      emptyOutDir: true,
      sourcemap: false,
      reportCompressedSize: false,
      minify: shouldMinify ? "esbuild" : false,
      cssMinify: shouldMinify ? "esbuild" : false,
      modulePreload: !isLowMemory,
      cssCodeSplit: !isLowMemory,
      chunkSizeWarningLimit: 1500,
      rollupOptions: {
        external: (id) => {
          if (id.includes(".md")) return true;
          if (!env.VITE_APP_PROJECT_EXCLUDE_LIST) return false;
          const excludeList = env.VITE_APP_PROJECT_EXCLUDE_LIST.split(",");
          return excludeList.some((item) => id.includes(item));
        },
