async function info(browser, url, w, h, label) {
  const page = await browser.newPage({ viewport: { width: w, height: h }, deviceScaleFactor: 1 })
  await page.route('**/fonts.googleapis.com/**', r => r.fulfill({ status: 200, contentType: 'text/css', body: '' }))
  await page.route('**/fonts.gstatic.com/**', r => r.abort())
  await page.goto(url, { waitUntil: 'domcontentloaded', timeout: 60000 })
  await page.waitForTimeout(2600)
  const d = await page.evaluate(() => {
    const root = document.querySelector('.mm-dashboard') || document.getElementById('root')
    const html = document.documentElement
    const body = document.body
    // 找到带 transform scale 的容器
    const all = Array.from(document.querySelectorAll('*'))
    const scaled = all.filter(e => { const t = getComputedStyle(e).transform; return t && t !== 'none' && t.includes('matrix') }).slice(0, 4)
    const rect = e => { const r = e.getBoundingClientRect(); return { x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height) } }
    return {
      inner: [window.innerWidth, window.innerHeight],
      dpr: window.devicePixelRatio,
      html: rect(html), body: rect(body),
      rootId: root && root.id, rootClass: root && root.className && String(root.className).slice(0, 80), root: root && rect(root),
      docScroll: [document.documentElement.scrollWidth, document.documentElement.scrollHeight],
      scaled: scaled.map(e => ({ tag: e.tagName, cls: String(e.className).slice(0, 70), transform: getComputedStyle(e).transform, rect: rect(e) })),
      firstKpi: (() => { const el = Array.from(document.querySelectorAll('*')).find(e => e.textContent && e.textContent.trim() === '商品房上市量'); return el ? rect(el) : null })(),
      headerH: (() => { const el = document.querySelector('header'); return el ? rect(el) : null })()
    }
  })
  console.log(label, JSON.stringify(d, null, 1))
  await page.close()
}
