const fs = require('fs')
const { PNG } = require('D:/repository/门户/node_modules/pngjs')
const { pathToFileURL } = require('url')
const dir = 'D:/repository/门户-wt-mme2e/test-results/mm-similarity'
;(async () => {
  const { default: pixelmatch } = await import(pathToFileURL('D:/repository/门户/node_modules/pixelmatch/index.js').href)
  const A = PNG.sync.read(fs.readFileSync(dir + '/ref-1366.png'))
  const B = PNG.sync.read(fs.readFileSync(dir + '/impl-1366.png'))
  const w = A.width, h = A.height
  let best = { pct: 0, dx: 0, dy: 0 }
  for (let dy = -6; dy <= 6; dy++) {
    for (let dx = -6; dx <= 6; dx++) {
      const diff = new PNG({ width: w, height: h })
      // 手动位移 B
      const shifted = new PNG({ width: w, height: h })
      for (let y = 0; y < h; y++) {
        for (let x = 0; x < w; x++) {
          const sx = x - dx, sy = y - dy
          const si = (sx >= 0 && sx < w && sy >= 0 && sy < h) ? (sy * w + sx) * 4 : -1
          const di = (y * w + x) * 4
          if (si >= 0) { shifted.data[di] = B.data[si]; shifted.data[di+1] = B.data[si+1]; shifted.data[di+2] = B.data[si+2]; shifted.data[di+3] = B.data[si+3] }
          else { shifted.data[di] = 255; shifted.data[di+1] = 255; shifted.data[di+2] = 255; shifted.data[di+3] = 255 }
        }
      }
      const n = pixelmatch(A.data, shifted.data, diff.data, w, h, { threshold: 0.1, includeAA: false })
      const pct = 100 * (1 - n / (w * h))
      if (pct > best.pct) best = { pct, dx, dy }
    }
  }
  console.log('best shift:', JSON.stringify(best))
})().catch(e => { console.error(e); process.exit(1) })

