  const d = await page.evaluate(() => {
    const f = e => { if (!e) return null; const r = e.getBoundingClientRect(); const s = getComputedStyle(e); return { cls: String(e.className||'').slice(0,95), y: +r.y.toFixed(2), h: +r.height.toFixed(2), cssH: s.height, gap: s.rowGap, pad: s.paddingTop + '/' + s.paddingBottom, flex: s.flex, minH: s.minHeight } }
