    const main = qs('main')
    const rows = main ? Array.from(main.children) : []
    return {
      header: f(qs('header')),
      main: f(main),
      mainChildren: rows.map(f),
      row1Children: rows[2] ? Array.from(rows[2].children).map(f) : [],
      row2Children: rows[3] ? Array.from(rows[3].children).map(f) : [],
