const { chromium } = require('D:/repository/门户/node_modules/playwright')
async function dump(browser, url, label) {
  const page = await browser.newPage({ viewport: { width: 1366, height: 768 }, deviceScaleFactor: 1 })
  await page.route('**/fonts.googleapis.com/**', r => r.fulfill({ status: 200, contentType: 'text/css', body: '' }))
  await page.route('**/fonts.gstatic.com/**', r => r.abort())
  await page.goto(url, { waitUntil: 'domcontentloaded', timeout: 60000 })
  await page.waitForTimeout(3000)
  const d = await page.evaluate(() => {
    const main = document.querySelector('main')
    const out = []
    const walk = (e, depth) => {
      if (depth > 7) return
      const r = e.getBoundingClientRect()
      out.push({ d: depth, tag: e.tagName, cls: String(e.className || '').slice(0, 110), h: +r.height.toFixed(1), txt: (e.children.length === 0 ? (e.textContent || '').trim().slice(0, 18) : '') })
      for (const c of e.children) walk(c, depth + 1)
    }
    walk(main, 0)
    return out
  })
  console.log(label, 'count', d.length)
  return d
}
;(async () => {
  const b = await chromium.launch({ headless: true })
  const a = await dump(b, 'http://localhost:3000/', 'REF')
  const c = await dump(b, 'http://127.0.0.1:8092/index.html#/market-monitor', 'IMPL')
  const n = Math.max(a.length, c.length)
  let diff = 0
  for (let i = 0; i < n; i++) {
    const x = a[i], y = c[i]
    if (!x || !y || x.tag !== y.tag || x.cls !== y.cls || Math.abs(x.h - y.h) > 1.5 || x.txt !== y.txt) {
      diff++
      if (diff <= 30) console.log('IDX', i, 'REF', JSON.stringify(x), 'IMPL', JSON.stringify(y))
    }
  }
  console.log('TOTAL DIFFS', diff)
  await b.close()
})().catch(e => { console.error(e); process.exit(1) })

