/**
 * 由「已对齐的 Vue 源码」生成离线单文件 market-monitor.standalone.html。
 *
 * 前置：zhi2-web-admin/standalone-build/ 脚手架（vite.standalone.config.mjs、
 *       entry.js、assemble-html.mjs）存在。该脚手架把 Vue2 运行时、echarts6、
 *       全部组件与样式内联成单一 HTML。
 *
 * 用法：node scripts/build-market-monitor-standalone.mjs
 */
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'
import { execFileSync } from 'node:child_process'

const repo = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const sub = path.join(repo, 'zhi2-web-admin')
const buildDir = path.join(sub, 'standalone-build')

for (const f of ['vite.standalone.config.mjs', 'entry.js', 'assemble-html.mjs']) {
  if (!fs.existsSync(path.join(buildDir, f))) {
    throw new Error(`缺少 standalone-build 脚手架: ${path.join(buildDir, f)}`)
  }
}

const run = (cmd, args) => {
  console.log('>', cmd, args.join(' '))
  execFileSync(cmd, args, { cwd: sub, stdio: 'inherit', shell: process.platform === 'win32' })
}

run('npx', ['vite', 'build', '--config', 'standalone-build/vite.standalone.config.mjs'])
run('node', ['standalone-build/assemble-html.mjs'])

const src = path.join(buildDir, 'market-monitor.standalone.html')
const dst = path.join(repo, 'market-monitor.standalone.html')
fs.copyFileSync(src, dst)
console.log('written', dst, fs.statSync(dst).size, 'bytes')
